package com.yuegang.zhihui.wallet.application;import com.yuegang.zhihui.wallet.security.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class WalletConfiguration{@Bean WalletService walletService(DataSource d){return new WalletService(d);}@Bean WalletQueryService walletQueryService(DataSource d){return new WalletQueryService(d);}@Bean WalletUserResolver walletUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new WalletUserResolver(k,Clock.systemUTC());}finally{Arrays.fill(k,(byte)0);}}}
